class Solution:
    def containsDuplicate(self, nums: List[int]) -> bool:
        """
        方法一：哈希集合（推薦）
        時間複雜度: O(n)
        空間複雜度: O(n)
        """
        seen = set()

        for num in nums:
            if num in seen:
                return True
            seen.add(num)

        return False

    def containsDuplicate_pythonic(self, nums: List[int]) -> bool:
        """
        方法一：Python 簡潔寫法
        """
        return len(nums) != len(set(nums))

    def containsDuplicate_sort(self, nums: List[int]) -> bool:
        """
        方法二：排序後比較
        時間複雜度: O(n log n)
        空間複雜度: O(1)
        """
        nums.sort()

        for i in range(len(nums) - 1):
            if nums[i] == nums[i + 1]:
                return True

        return False

