#include <vector>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    /**
     * 方法一：哈希集合（推薦）
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    bool containsDuplicate(vector<int>& nums) {
        unordered_set<int> seen;

        for (int num : nums) {
            if (seen.count(num) > 0) {
                return true;
            }
            seen.insert(num);
        }

        return false;
    }

    /**
     * 方法二：排序後比較
     * 時間複雜度: O(n log n)
     * 空間複雜度: O(1)
     */
    bool containsDuplicate_sort(vector<int>& nums) {
        sort(nums.begin(), nums.end());

        for (int i = 0; i < nums.size() - 1; i++) {
            if (nums[i] == nums[i + 1]) {
                return true;
            }
        }

        return false;
    }
};

